   772  void icalproperty_set_value_from_string(icalproperty *prop, const char *str, const char *type)
   773  {
   774      icalvalue *oval, *nval;
   775      icalvalue_kind kind = ICAL_NO_VALUE;
   776
   777      icalerror_check_arg_rv((prop != 0), "prop");
   778      icalerror_check_arg_rv((str != 0), "str");
   779      icalerror_check_arg_rv((type != 0), "type");
   780
   781      if (strcmp(type, "NO") == 0) {
   782          /* Get the type from the value the property already has, if it exists */
   783          oval = icalproperty_get_value(prop);
   784          if (oval != 0) {
   785              /* Use the existing value kind */
   786              kind = icalvalue_isa(oval);
   787          } else {
   788              /* Use the default kind for the property */
   789              kind = icalproperty_kind_to_value_kind(icalproperty_isa(prop));
   790          }
   791      } else {
   792          /* Use the given kind string */
   793          kind = icalvalue_string_to_kind(type);
   794      }
   795
   796      if (kind == ICAL_NO_VALUE) {
   797          icalerror_set_errno(ICAL_MALFORMEDDATA_ERROR);
   798          return;
   799      }
   800
   801      icalerror_clear_errno();
   802      nval = icalvalue_new_from_string(kind, str);
   803
   804      if (nval == 0) {
   805          /* icalvalue_new_from_string sets errno */
   806          icalassert(icalerrno != ICAL_NO_ERROR);
   807          return;
   808      }
   809
   810      icalproperty_set_value(prop, nval);
   811  }
